use arrow_array::{Array, PrimitiveArray, cast::AsArray, types::*};
use arrow_buffer::i256;
use arrow_cast::{CastOptions, cast_with_options};

#[test]
fn large_integer_decimal_values() {
    fn check<T, D>(values: Vec<T::Native>, digits: u8) -> usize
    where
        T: ArrowPrimitiveType,
        T::Native: Into<i128>,
        D: DecimalType,
        D::Native: std::fmt::Display,
    {
        if digits > D::MAX_PRECISION {
            return 0;
        }
        let mut cases = 0;
        for bytes in [64 * 1024, 128 * 1024, 256 * 1024] {
            let rows = bytes / size_of::<D::Native>();
            let input = PrimitiveArray::<T>::from_iter(
                (0..rows + 2).map(|i| (i % 7 != 0).then_some(values[i % values.len()])),
            )
            .slice(1, rows);
            for scale in [0, (D::MAX_PRECISION - digits) as i8] {
                let factor = i256::from_i128(10).checked_pow(scale as u32).unwrap();
                let target = PrimitiveArray::<D>::new_null(0)
                    .with_precision_and_scale(D::MAX_PRECISION, scale)
                    .unwrap();
                let expected = input
                    .iter()
                    .map(|v| {
                        v.map(|v| {
                            i256::from_i128(v.into())
                                .checked_mul(factor)
                                .unwrap()
                                .to_string()
                        })
                    })
                    .collect::<Vec<_>>();
                for safe in [false, true] {
                    let output = cast_with_options(
                        &input,
                        target.data_type(),
                        &CastOptions {
                            safe,
                            ..Default::default()
                        },
                    )
                    .unwrap();
                    assert_eq!(output.data_type(), target.data_type());
                    assert_eq!(
                        output
                            .as_primitive::<D>()
                            .iter()
                            .map(|v| v.map(|v| v.to_string()))
                            .collect::<Vec<_>>(),
                        expected
                    );
                    let cloned = output.slice(1, rows - 2);
                    drop(output);
                    let other = cast_with_options(
                        &PrimitiveArray::<T>::new_null(rows),
                        target.data_type(),
                        &CastOptions {
                            safe,
                            ..Default::default()
                        },
                    )
                    .unwrap();
                    assert_eq!(other.null_count(), rows);
                    assert_eq!(
                        cloned
                            .as_primitive::<D>()
                            .iter()
                            .map(|v| v.map(|v| v.to_string()))
                            .collect::<Vec<_>>(),
                        expected[1..rows - 1]
                    );
                    std::thread::spawn(move || drop(cloned)).join().unwrap();
                    cases += 1;
                }
            }
        }
        cases
    }
    let mut cases = 0;
    macro_rules! check_integer {
        ($arrow:ty, $native:ty, $digits:expr) => {{
            let values = vec![<$native>::MIN, <$native>::MAX, 0, 1];
            cases += check::<$arrow, Decimal32Type>(values.clone(), $digits);
            cases += check::<$arrow, Decimal64Type>(values.clone(), $digits);
            cases += check::<$arrow, Decimal128Type>(values.clone(), $digits);
            cases += check::<$arrow, Decimal256Type>(values, $digits);
        }};
    }
    check_integer!(Int8Type, i8, 3);
    check_integer!(UInt8Type, u8, 3);
    check_integer!(Int16Type, i16, 5);
    check_integer!(UInt16Type, u16, 5);
    check_integer!(Int32Type, i32, 10);
    check_integer!(UInt32Type, u32, 10);
    check_integer!(Int64Type, i64, 19);
    check_integer!(UInt64Type, u64, 20);
    assert_eq!(cases, 312);
    println!("{cases} large casts, all-NULL outputs and retained cross-thread slices passed");
}

#[test]
fn concurrent_casts_preserve_live_outputs() {
    let barrier = std::sync::Arc::new(std::sync::Barrier::new(4));
    let threads = (0..4)
        .map(|thread| {
            let barrier = barrier.clone();
            std::thread::spawn(move || {
                barrier.wait();
                let mut retained = Vec::new();
                for step in 0..128 {
                    let value = (thread * 128 + step) as i64;
                    let input = arrow_array::Int64Array::from(vec![Some(value), None].repeat(4096));
                    let out = cast_with_options(
                        &input,
                        &arrow_schema::DataType::Decimal128(38, 6),
                        &CastOptions::default(),
                    )
                    .unwrap();
                    retained.push((value, out));
                    if retained.len() > 3 {
                        let (expected, old) = retained.remove(0);
                        assert_eq!(old.null_count(), 4096);
                        assert!(
                            old.as_primitive::<Decimal128Type>()
                                .iter()
                                .flatten()
                                .all(|v| v == i128::from(expected) * 1_000_000)
                        );
                    }
                }
                for (expected, old) in retained {
                    assert!(
                        old.as_primitive::<Decimal128Type>()
                            .iter()
                            .flatten()
                            .all(|v| v == i128::from(expected) * 1_000_000)
                    );
                }
            })
        })
        .collect::<Vec<_>>();
    for thread in threads {
        thread.join().unwrap();
    }
}

