import json, statistics
from pathlib import Path

p = Path(__file__).parent
data = json.loads((p / 'performance.json').read_text())
assert len(data['runs']) == 224
summary = {}
for mode in data['modes']:
    summary[mode] = {}
    for case in data['targets'] + [data['control']]:
        entry = {}
        for variant in ['before', 'after']:
            runs = [r for r in data['runs'] if (r['mode'], r['case'], r['variant']) == (mode, case, variant)]
            assert len(runs) == (4 if case == data['control'] else 12)
            times = [r['median_ms'] for r in runs]
            entry[variant] = {'processes': len(runs), 'median_ms': statistics.median(times), 'mean_ms': statistics.mean(times), 'range_ms': [min(times), max(times)], 'page_fault_values': sorted({r['page_faults'] for r in runs}), 'high_fault_processes': sum(r['page_faults'] > 1000 for r in runs)}
        entry['median_change_percent'] = (entry['after']['median_ms'] / entry['before']['median_ms'] - 1) * 100
        summary[mode][case] = entry
    print(mode, {case: {v: (round(summary[mode][case][v]['median_ms'], 3), summary[mode][case][v]['high_fault_processes']) for v in ['before', 'after']} for case in data['targets'] + [data['control']]}, flush=True)
(p / 'summary.json').write_text(json.dumps(summary, indent=2) + '\n')
memory = json.loads((p / 'memory.json').read_text())
assert len(memory['runs']) == 16
memory_summary = {}
for variant in memory['variants']:
    runs = [r for r in memory['runs'] if r['variant'] == variant]
    memory_summary[variant] = {key: statistics.median(r[key] for r in runs) for key in ['rss_after_kib', 'private_dirty_after_kib', 'peak_rss_after_kib']}
(p / 'memory-summary.json').write_text(json.dumps(memory_summary, indent=2) + '\n')
